USE student_growth;

CREATE TABLE wrong_question(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,exam_id BIGINT NULL,source_type VARCHAR(32) NOT NULL,source_name VARCHAR(128),question_type VARCHAR(32),question_text LONGTEXT NOT NULL,student_answer LONGTEXT,correct_answer LONGTEXT,answer_source VARCHAR(32),analysis_text LONGTEXT,analysis_source VARCHAR(32),error_type VARCHAR(32),difficulty TINYINT,status VARCHAR(32) NOT NULL DEFAULT 'NEW',review_stage INT NOT NULL DEFAULT 0,review_count INT NOT NULL DEFAULT 0,last_review_time DATETIME(3),next_review_time DATETIME(3),occurred_date DATE,remark TEXT,deleted TINYINT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 0,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT fk_wq_student FOREIGN KEY(student_id) REFERENCES student(id),CONSTRAINT fk_wq_subject FOREIGN KEY(subject_id) REFERENCES subject(id),CONSTRAINT fk_wq_exam FOREIGN KEY(exam_id) REFERENCES exam(id),CHECK(source_type IN('PRACTICE','EXAM')),CHECK(difficulty IS NULL OR difficulty BETWEEN 1 AND 5),CHECK(review_stage BETWEEN 0 AND 7),INDEX idx_wq_filter(student_id,subject_id,source_type,status,deleted),INDEX idx_wq_review(next_review_time,status,deleted)) ENGINE=InnoDB;

CREATE TABLE wrong_question_knowledge(wrong_question_id BIGINT NOT NULL,knowledge_id BIGINT NOT NULL,is_primary TINYINT NOT NULL DEFAULT 0,confidence DECIMAL(5,4),PRIMARY KEY(wrong_question_id,knowledge_id),CONSTRAINT fk_wqk_wq FOREIGN KEY(wrong_question_id) REFERENCES wrong_question(id),CONSTRAINT fk_wqk_kn FOREIGN KEY(knowledge_id) REFERENCES knowledge_node(id),CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1)) ENGINE=InnoDB;

CREATE TABLE wrong_review(id BIGINT PRIMARY KEY AUTO_INCREMENT,wrong_question_id BIGINT NOT NULL,review_time DATETIME(3) NOT NULL,result VARCHAR(16) NOT NULL,score DECIMAL(8,2),duration_seconds INT,student_answer LONGTEXT,remark TEXT,next_review_time DATETIME(3),idempotency_key VARCHAR(64),create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),CONSTRAINT fk_wr_wq FOREIGN KEY(wrong_question_id) REFERENCES wrong_question(id),CHECK(result IN('CORRECT','PARTIAL','WRONG','UNKNOWN')),UNIQUE KEY uk_wr_idempotency(idempotency_key)) ENGINE=InnoDB;
